import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2020-09-10","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-09-10","date":"2020-09-10T00:00:00.000Z","updated":"2020-09-11T00:00:00.000Z","tags":["Ceph","Distributed Storage","Performance Optimization","BlueStore","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-09-10.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-09-10.md","lastUpdated":1780460162000}'),i={name:"posts/2020/Ceph_Performance_Meeting_2020-09-10.md"};function l(n,e,s,h,g,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2020-09-10" tabindex="-1">会议时间：2020-09-10 <a class="header-anchor" href="#会议时间-2020-09-10" aria-label="Permalink to &quot;会议时间：2020-09-10&quot;">​</a></h4><h4 id="参会人员-josh-kifu-igor-等" tabindex="-1">参会人员：Josh, Kifu, Igor 等 <a class="header-anchor" href="#参会人员-josh-kifu-igor-等" aria-label="Permalink to &quot;参会人员：Josh, Kifu, Igor 等&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>Ceph项目进展更新</strong></li><li><strong>讨论和优化Ceph中的OSD异步恢复机制</strong></li><li><strong>改进Ceph中的BlueStore删除流程</strong></li></ol><h4 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h4><ul><li><strong>Josh</strong> 报告了Ceph项目的PR进展，特别是关于off-monitor PR的关闭和合并情况。</li><li><strong>讨论了OSD异步恢复机制</strong>，目前考虑保持默认设置，但仍需进一步讨论。</li><li><strong>发现测试结果可能因错误的crash规则导致结果不可靠</strong>，需等待进一步测试结果。</li><li><strong>Kifu</strong> 提到了优化BlueStore的PR，该PR曾被关闭后又重新打开，但目前没有新的进展。</li></ul><h4 id="重点讨论" tabindex="-1">重点讨论： <a class="header-anchor" href="#重点讨论" aria-label="Permalink to &quot;重点讨论：&quot;">​</a></h4><ul><li><strong>Igor</strong> 详细介绍了Ceph中删除操作的当前流程和存在的问题，包括删除速度慢、空间回收时间长等。</li><li><strong>提出了几种改进方案</strong>，包括调整删除任务的休眠时间、使用更高效的数据库操作等。</li><li><strong>展示了新的删除流程设计</strong>，通过先回收空间再进行数据库记录的删除，以提高效率。</li><li><strong>进行了性能测试</strong>，对比了不同删除策略的性能，包括原始删除流程和改进后的流程。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>继续讨论和优化OSD异步恢复机制</strong>，特别是关于默认设置的讨论。</li><li><strong>进一步测试和验证Igor提出的删除流程改进方案</strong>，包括性能和稳定性的测试。</li><li><strong>计划在下一次会议继续讨论Ceph的优化和改进</strong>，特别是关于BlueStore的删除流程。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>Igor</strong> 将继续进行删除流程的性能测试和优化，特别是关于使用删除范围功能的测试。</li><li><strong>团队成员</strong> 将继续关注和参与Ceph项目的PR审查和讨论，确保项目的稳定性和性能。</li><li><strong>下一次会议</strong> 将继续讨论Ceph的优化和改进，特别是关于BlueStore的删除流程和其他相关议题。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li><strong>Igor</strong> 将分享他的测试结果和幻灯片，供团队成员进一步分析和讨论。</li><li><strong>会议时间</strong> 已充分利用，下一次会议将继续深入讨论Ceph的优化和改进。</li></ul>',15)])])}const p=r(i,[["render",l]]);export{c as __pageData,p as default};
